window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q121","domains":[3],"level":1,"tag":"Stakeholder","q":"A project team has listed department heads but not frontline staff who will use the new intake process. What should the BA do first when planning stakeholder engagement?","opts":["Start scheduling interviews with department heads, then ask them to nominate users","Analyze who is affected by the need and change, including users and other relevant groups","Ask the sponsor to approve requirements before identifying additional participants","Choose a collaboration technique and treat attendees as the complete stakeholder list"],"answer":[1],"why":["This choice does not best address the issue: Identify stakeholders from the need and affected parts of the enterprise, then analyze them to plan engagement.","Correct: Identify stakeholders from the need and affected parts of the enterprise, then analyze them to plan engagement.","This choice does not best address the issue: Identify stakeholders from the need and affected parts of the enterprise, then analyze them to plan engagement.","This choice does not best address the issue: Identify stakeholders from the need and affected parts of the enterprise, then analyze them to plan engagement."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q122","domains":[3],"level":1,"tag":"Stakeholder","q":"Two stakeholders share a job title, but one approves policy changes while the other supplies operational data. What best reflects stakeholder analysis?","opts":["Classify both identically because job title is the most consistent indicator","Invite both to every activity so their differing responsibilities do not affect the plan","Record their distinct roles, authority, interests, and needed participation before choosing engagement approaches","Let each choose their own involvement after elicitation is complete"],"answer":[2],"why":["This choice does not best address the issue: Analyze characteristics relevant to engagement, such as roles, authority, interests, and participation needs.","This choice does not best address the issue: Analyze characteristics relevant to engagement, such as roles, authority, interests, and participation needs.","Correct: Analyze characteristics relevant to engagement, such as roles, authority, interests, and participation needs.","This choice does not best address the issue: Analyze characteristics relevant to engagement, such as roles, authority, interests, and participation needs."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q123","domains":[3],"level":1,"tag":"Stakeholder","q":"A remote supplier has little decision authority but controls information needed to understand a key interface. How should the BA reflect this in the engagement plan?","opts":["Include the supplier because relevant knowledge and information access matter even without approval authority","Exclude the supplier because only approvers need engagement","Ask the project manager to provide a substitute opinion","Wait until design approval to contact the supplier"],"answer":[0],"why":["Correct: Stakeholders are not limited to approvers; the supplier's information and expertise are relevant to the change.","This choice does not best address the issue: Stakeholders are not limited to approvers; the supplier's information and expertise are relevant to the change.","This choice does not best address the issue: Stakeholders are not limited to approvers; the supplier's information and expertise are relevant to the change.","This choice does not best address the issue: Stakeholders are not limited to approvers; the supplier's information and expertise are relevant to the change."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q124","domains":[3],"level":1,"tag":"Stakeholder","q":"A stakeholder is publicly supportive but privately concerned the change will reduce local autonomy. What is the most useful planning response?","opts":["Record the stakeholder as supportive and use the same communication plan for all groups","Treat the concern as opposition and remove them from decision discussions","Escalate the attitude to the sponsor without further analysis","Explore the concern and its likely effect on participation, then tailor communication and collaboration"],"answer":[3],"why":["This choice does not best address the issue: Understand stakeholder characteristics and engagement risks, then choose suitable collaboration and communication approaches.","This choice does not best address the issue: Understand stakeholder characteristics and engagement risks, then choose suitable collaboration and communication approaches.","This choice does not best address the issue: Understand stakeholder characteristics and engagement risks, then choose suitable collaboration and communication approaches.","Correct: Understand stakeholder characteristics and engagement risks, then choose suitable collaboration and communication approaches."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q125","domains":[3],"level":2,"tag":"Stakeholder","q":"During a workshop participants agree on the current process but disagree about why exceptions occur. What should the BA do while conducting elicitation?","opts":["Record only the shared view and close the topic to protect the schedule","Use follow-up questions or another suitable technique to explore the differing explanations","Declare the most senior participant's explanation to be the result","Move directly to approval so disagreement becomes a change request"],"answer":[1],"why":["This choice does not best address the issue: Elicitation draws out, explores, and identifies relevant information; follow-up is appropriate when accounts differ.","Correct: Elicitation draws out, explores, and identifies relevant information; follow-up is appropriate when accounts differ.","This choice does not best address the issue: Elicitation draws out, explores, and identifies relevant information; follow-up is appropriate when accounts differ.","This choice does not best address the issue: Elicitation draws out, explores, and identifies relevant information; follow-up is appropriate when accounts differ."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q126","domains":[3],"level":2,"tag":"Stakeholder","q":"Users cannot explain a rare system failure because they have never observed its trigger. Which elicitation approach best uncovers information not known by participants?","opts":["Interview users asking them to recall what they have never seen","Review only approved requirements","Use an experiment or controlled test, such as a prototype or proof of concept","Ask users to confirm the current notes"],"answer":[2],"why":["This choice does not best address the issue: Experiments can discover information that cannot be drawn from people or documents, such as through prototypes or controlled tests.","This choice does not best address the issue: Experiments can discover information that cannot be drawn from people or documents, such as through prototypes or controlled tests.","Correct: Experiments can discover information that cannot be drawn from people or documents, such as through prototypes or controlled tests.","This choice does not best address the issue: Experiments can discover information that cannot be drawn from people or documents, such as through prototypes or controlled tests."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q127","domains":[3],"level":2,"tag":"Stakeholder","q":"A BA is preparing a short session with several stakeholder groups. Which action best supports effective elicitation?","opts":["Use the elicitation activity plan to guide scope, logistics, techniques, and supporting materials","Let participants choose any topic and determine the scope during the session","Finalize requirements first so the group can focus on approval","Use one technique throughout even if it fails to produce needed information"],"answer":[0],"why":["Correct: The elicitation activity plan guides the activity, including scope, logistics, selected techniques, and supporting materials.","This choice does not best address the issue: The elicitation activity plan guides the activity, including scope, logistics, selected techniques, and supporting materials.","This choice does not best address the issue: The elicitation activity plan guides the activity, including scope, logistics, selected techniques, and supporting materials.","This choice does not best address the issue: The elicitation activity plan guides the activity, including scope, logistics, selected techniques, and supporting materials."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q128","domains":[3],"level":2,"tag":"Stakeholder","q":"A BA reviews prior support logs and interviews service agents to understand recurring complaints. How should these activities be characterized?","opts":["Both are experiments because they examine behavior","The log review is research and interviews are collaborative elicitation","The log review is confirmation and interviews are formal approval","Both are stakeholder collaboration because agents work with the BA"],"answer":[1],"why":["This choice does not best address the issue: Studying existing logs is research, while direct interaction with agents is collaborative elicitation.","Correct: Studying existing logs is research, while direct interaction with agents is collaborative elicitation.","This choice does not best address the issue: Studying existing logs is research, while direct interaction with agents is collaborative elicitation.","This choice does not best address the issue: Studying existing logs is research, while direct interaction with agents is collaborative elicitation."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q129","domains":[3],"level":3,"tag":"Stakeholder","q":"Executives need a decision summary while analysts need detailed process models. Which communication choice best supports shared understanding?","opts":["Send the full model to everyone","Send the executive summary to everyone","Tailor format and detail to each audience while preserving consistent underlying information","Ask each group to create its own version"],"answer":[2],"why":["This choice does not best address the issue: Plan communication for audience and purpose, with appropriate format and detail while supporting shared understanding.","This choice does not best address the issue: Plan communication for audience and purpose, with appropriate format and detail while supporting shared understanding.","Correct: Plan communication for audience and purpose, with appropriate format and detail while supporting shared understanding.","This choice does not best address the issue: Plan communication for audience and purpose, with appropriate format and detail while supporting shared understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q130","domains":[3],"level":3,"tag":"Stakeholder","q":"A requirements package was sent, but stakeholders interpreted a term differently. What is the best next step?","opts":["Assume receipt establishes shared understanding and continue to design","Clarify the intended meaning with the audience and adjust the communication or information","Replace the term in the repository without notifying stakeholders","Ask the sponsor to choose one interpretation and treat it as agreed"],"answer":[1],"why":["This choice does not best address the issue: Communication aims at shared understanding; clarify the meaning and improve the communication as needed.","Correct: Communication aims at shared understanding; clarify the meaning and improve the communication as needed.","This choice does not best address the issue: Communication aims at shared understanding; clarify the meaning and improve the communication as needed.","This choice does not best address the issue: Communication aims at shared understanding; clarify the meaning and improve the communication as needed."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q131","domains":[3],"level":3,"tag":"Stakeholder","q":"A confidential decision rationale must be shared with a cross-functional group. What should the BA consider?","opts":["The audience's information needs and access constraints, and a suitable way to communicate the rationale","Whether it can be sent to all employees to maximize transparency","Whether to omit the rationale so the decision cannot be challenged","Whether every recipient can access the repository regardless of need"],"answer":[0],"why":["Correct: Account for audience, purpose, format, and constraints so the intended stakeholders receive appropriate information.","This choice does not best address the issue: Account for audience, purpose, format, and constraints so the intended stakeholders receive appropriate information.","This choice does not best address the issue: Account for audience, purpose, format, and constraints so the intended stakeholders receive appropriate information.","This choice does not best address the issue: Account for audience, purpose, format, and constraints so the intended stakeholders receive appropriate information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q132","domains":[3],"level":3,"tag":"Stakeholder","q":"A stakeholder says a model is clear, but then describes a different process from the one it depicts. What should the BA infer?","opts":["The stakeholder accepted the model because they said it was clear","The sponsor should approve the model before discussion continues","The stakeholder's interpretation is authoritative","Shared understanding has not been established; clarify the model and check interpretation"],"answer":[3],"why":["This choice does not best address the issue: The differing interpretation signals a need to clarify and confirm; sending or acknowledging information does not prove shared understanding.","This choice does not best address the issue: The differing interpretation signals a need to clarify and confirm; sending or acknowledging information does not prove shared understanding.","This choice does not best address the issue: The differing interpretation signals a need to clarify and confirm; sending or acknowledging information does not prove shared understanding.","Correct: The differing interpretation signals a need to clarify and confirm; sending or acknowledging information does not prove shared understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q133","domains":[3],"level":4,"tag":"Stakeholder","q":"Two stakeholder groups repeatedly interrupt one another and withhold information in joint sessions. What should the BA do?","opts":["Cancel joint sessions and gather each group's information separately without reconciling it","Facilitate discussion of the conflict, establish workable participation norms, and focus groups on the shared change","Allow the more influential group to set the agenda and answer for both","Stop engaging either group until leadership decides"],"answer":[1],"why":["This choice does not best address the issue: Enable participation and address conflict so stakeholders can work together toward the change.","Correct: Enable participation and address conflict so stakeholders can work together toward the change.","This choice does not best address the issue: Enable participation and address conflict so stakeholders can work together toward the change.","This choice does not best address the issue: Enable participation and address conflict so stakeholders can work together toward the change."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q134","domains":[3],"level":4,"tag":"Stakeholder","q":"A critical stakeholder repeatedly misses elicitation sessions because of operational duties. What is the most appropriate response?","opts":["Mark them uncooperative and proceed using assumptions","Ask the sponsor to replace them with someone more available","Discuss the participation barrier and adjust the collaboration approach or timing where feasible","Send notes after a solution has been selected"],"answer":[2],"why":["This choice does not best address the issue: Work with stakeholders to enable participation and adapt collaboration arrangements to the context.","This choice does not best address the issue: Work with stakeholders to enable participation and adapt collaboration arrangements to the context.","Correct: Work with stakeholders to enable participation and adapt collaboration arrangements to the context.","This choice does not best address the issue: Work with stakeholders to enable participation and adapt collaboration arrangements to the context."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q135","domains":[3],"level":4,"tag":"Stakeholder","q":"A decision meeting is dominated by senior voices while affected staff remain silent. Which facilitation move best supports collaboration?","opts":["Use a structured round or similar technique that gives affected participants a workable opportunity to contribute","Treat silence as agreement and record approval","Ask senior stakeholders to summarize what staff would probably say","End the meeting and request approval from senior participants only"],"answer":[0],"why":["Correct: Use facilitation approaches that encourage participation and surface perspectives from affected stakeholders.","This choice does not best address the issue: Use facilitation approaches that encourage participation and surface perspectives from affected stakeholders.","This choice does not best address the issue: Use facilitation approaches that encourage participation and surface perspectives from affected stakeholders.","This choice does not best address the issue: Use facilitation approaches that encourage participation and surface perspectives from affected stakeholders."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q136","domains":[3],"level":4,"tag":"Stakeholder","q":"An initially supportive stakeholder becomes disengaged after a proposed workflow changes. What should the BA do?","opts":["Keep the engagement plan unchanged to avoid appearing reactive","Ask the sponsor to compel participation before exploring the cause","Remove the stakeholder from future work","Revisit the stakeholder's concerns and the change's effect, then adapt collaboration to restore useful participation"],"answer":[3],"why":["This choice does not best address the issue: Understand the cause of disengagement and adapt collaboration so the stakeholder can participate meaningfully.","This choice does not best address the issue: Understand the cause of disengagement and adapt collaboration so the stakeholder can participate meaningfully.","This choice does not best address the issue: Understand the cause of disengagement and adapt collaboration so the stakeholder can participate meaningfully.","Correct: Understand the cause of disengagement and adapt collaboration so the stakeholder can participate meaningfully."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q137","domains":[3],"level":5,"tag":"Stakeholder","q":"A business owner agrees with a requirement's wording, but the designated approval authority has not reviewed it. What is the correct status?","opts":["Approved because a knowledgeable stakeholder agrees","Rejected because the approval authority did not attend","Validated because the wording was reviewed","Awaiting the required approval, not yet approved"],"answer":[3],"why":["This choice does not best address the issue: Do not represent the requirement as approved until the applicable approval is obtained.","This choice does not best address the issue: Do not represent the requirement as approved until the applicable approval is obtained.","This choice does not best address the issue: Do not represent the requirement as approved until the applicable approval is obtained.","Correct: Do not represent the requirement as approved until the applicable approval is obtained."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q138","domains":[3],"level":5,"tag":"Stakeholder","q":"An authorized approver refuses a requirement because it conflicts with a policy decision. What should the BA do next?","opts":["Change the requirement to match policy without recording the decision","Mark it conditionally approved so downstream work can continue","Record the outcome and rationale, communicate status, and determine follow-up with relevant stakeholders","Remove it and leave its status unchanged"],"answer":[2],"why":["This choice does not best address the issue: Make approval outcomes and status clear; document and communicate the decision, then determine appropriate follow-up.","This choice does not best address the issue: Make approval outcomes and status clear; document and communicate the decision, then determine appropriate follow-up.","Correct: Make approval outcomes and status clear; document and communicate the decision, then determine appropriate follow-up.","This choice does not best address the issue: Make approval outcomes and status clear; document and communicate the decision, then determine appropriate follow-up."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q139","domains":[3],"level":5,"tag":"Stakeholder","q":"A requirement has unresolved dependencies, and a stakeholder asks the BA to seek approval immediately to protect the schedule. What is the best response?","opts":["Seek approval now and resolve dependencies only if they affect implementation","Ask the most influential stakeholder to approve on behalf of others","Delay all approval until every design detail is complete","Make the dependency and implications visible, then follow the agreed review and approval process when ready"],"answer":[3],"why":["This choice does not best address the issue: Disclose relevant dependencies and use the agreed process so authorized stakeholders can make an informed decision.","This choice does not best address the issue: Disclose relevant dependencies and use the agreed process so authorized stakeholders can make an informed decision.","This choice does not best address the issue: Disclose relevant dependencies and use the agreed process so authorized stakeholders can make an informed decision.","Correct: Disclose relevant dependencies and use the agreed process so authorized stakeholders can make an informed decision."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q140","domains":[3],"level":5,"tag":"Stakeholder","q":"Different groups support a requirement for different reasons, and one group believes approval means the design is final. What should the BA do before closing approval?","opts":["Confirm the decision and ensure stakeholders understand what was approved and what remains outside its scope","Treat approval as acceptance of the final design","Ask only the sponsor to interpret the decision after filing","Reopen every requirement because stakeholders had different reasons"],"answer":[0],"why":["Correct: Communicate the approval outcome and scope so stakeholders understand what the decision does and does not establish.","This choice does not best address the issue: Communicate the approval outcome and scope so stakeholders understand what the decision does and does not establish.","This choice does not best address the issue: Communicate the approval outcome and scope so stakeholders understand what the decision does and does not establish.","This choice does not best address the issue: Communicate the approval outcome and scope so stakeholders understand what the decision does and does not establish."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-17.html"},{"id":"q141","domains":[3],"level":1,"tag":"Stakeholder","q":"A sponsor asks the BA to begin planning workshops using the current attendee list. The list contains managers but no employees who perform the affected work. What is the best next step?","opts":["Keep the list and ask managers to relay questions to employees","Analyze the need and affected parts of the enterprise to identify relevant stakeholder groups before finalizing engagement","Add every employee in the organization so no affected person can be missed","Schedule the workshops first and use attendance to determine who the stakeholders are"],"answer":[1],"why":["Managers may provide useful input, but relaying questions does not establish that affected employees have been identified or engaged.","Correct: identify stakeholders in relation to the need and affected areas, then analyze their characteristics to plan engagement.","Including everyone ignores relevance and can make engagement impractical; identify those connected to the change.","Attendance after scheduling can reveal gaps too late to plan effective participation."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q142","domains":[3],"level":1,"tag":"Stakeholder","q":"Two stakeholders are equally affected by a change, but one can authorize funding while the other has detailed knowledge of daily workarounds. What should the BA do when planning engagement?","opts":["Give both identical roles in every decision because their impact is equal","Engage only the funding authority because approval power determines relevance","Use the funding authority to validate the workarounds on behalf of users","Reflect their different authority and expertise in the planned collaboration and communication"],"answer":[3],"why":["Equal impact does not mean identical responsibilities or engagement needs.","Approval power is important but does not make operational expertise irrelevant.","A funding authority may not have the firsthand knowledge needed to validate operational workarounds.","Correct: stakeholder characteristics such as role, authority, knowledge, and interests inform how each should be engaged."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q143","domains":[3],"level":1,"tag":"Stakeholder","q":"A stakeholder has limited influence over decisions but is likely to experience a significant negative effect from the proposed change. Which assessment is most useful to engagement planning?","opts":["Record the stakeholder's impact and concerns, then consider how to obtain meaningful input and manage engagement risk","Classify the stakeholder as low priority because influence is limited","Ask a more influential stakeholder to represent the affected person's interests","Delay engagement until the change is approved to avoid raising concerns"],"answer":[0],"why":["Correct: influence is only one relevant characteristic; impact and concerns can indicate a need for deliberate engagement and risk planning.","Low influence does not mean low impact or that the person's perspective can be ignored.","A representative may not accurately convey the affected stakeholder's experience; direct input should be considered.","Deferring engagement may prevent the BA from understanding impacts while options can still be considered."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q144","domains":[3],"level":1,"tag":"Stakeholder","q":"A distributed stakeholder group has different working hours and prefers different communication channels. What should the BA establish in the engagement plan?","opts":["One channel and one meeting time to ensure equal treatment","A separate, unrelated approach for each stakeholder with no common information baseline","Suitable collaboration and communication approaches that account for stakeholder characteristics while maintaining a consistent purpose","A requirement that every stakeholder adapt to the project team's normal schedule"],"answer":[2],"why":["Uniformity can reduce participation when access and schedules differ.","Completely separate approaches can create inconsistent information and misalignment.","Correct: plan approaches suited to stakeholder characteristics while supporting consistent engagement around the initiative.","Imposing one schedule may exclude stakeholders whose input is needed; the approach should consider their circumstances."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q145","domains":[3],"level":2,"tag":"Stakeholder","q":"In an interview, a stakeholder says a delay is caused by an approval step. The BA's process data suggests the delay occurs before approval. What should the BA do during elicitation?","opts":["Accept the stakeholder's account because interviews are direct evidence","Record both explanations as confirmed facts and move to solution design","Ask a different stakeholder to decide which explanation is correct","Probe the discrepancy and use suitable follow-up elicitation to understand the sequence and cause"],"answer":[3],"why":["A stakeholder account is valuable evidence but should be explored when it conflicts with other information.","Conflicting explanations are not both confirmed facts; the cause remains unresolved.","Another stakeholder may add evidence, but delegating the judgment does not itself elicit the missing detail.","Correct: conducting elicitation includes drawing out and exploring relevant information, including discrepancies that need follow-up."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q146","domains":[3],"level":2,"tag":"Stakeholder","q":"A compliance team can describe the rule but cannot predict how a new automated control will behave under unusual load. Which approach is most likely to reveal that unknown behavior?","opts":["Repeat interviews until participants agree on the expected behavior","Use a controlled experiment or prototype to observe behavior under representative conditions","Review the approved requirement wording without testing it","Ask the approval authority to decide how the control should behave"],"answer":[1],"why":["Agreement about expectations does not reveal actual behavior under conditions participants cannot predict.","Correct: experiments can uncover information that is not known through people or existing materials, including with prototypes or controlled tests.","Requirement review may clarify intended behavior but does not expose runtime behavior under unusual load.","An approval decision may set policy but does not generate evidence about the system's behavior."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q147","domains":[3],"level":2,"tag":"Stakeholder","q":"A workshop is intended to explore handoffs among three departments, but participants begin debating detailed screen labels. What should the facilitator do?","opts":["Redirect the discussion to the planned handoff scope and capture screen labels for a suitable later activity","Allow the discussion to continue because all details are potentially relevant","End the workshop and ask participants to approve the screen labels","Remove the screen-label discussion from the record because it was out of scope"],"answer":[0],"why":["Correct: keep elicitation aligned to the activity's planned scope while capturing relevant follow-up topics for appropriate treatment.","Without redirection, the activity may not achieve its intended outcome or cover the handoffs.","The session is exploring handoffs, not necessarily eliciting or approving final screen requirements.","Relevant information should not be discarded merely because it arose outside the current scope; record it for follow-up."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q148","domains":[3],"level":2,"tag":"Stakeholder","q":"After reviewing policy documents, a BA interviews policy owners to understand how an exception is applied in practice. Which description is most accurate?","opts":["Both are experiments because the BA is comparing sources","The document review confirms results and the interviews approve them","Document review is research; interviews are collaborative elicitation","Both activities are confirmation because the policy already exists"],"answer":[2],"why":["Comparing sources is not a controlled test; the document review is research and interviews involve direct collaboration.","The purpose is to discover how exceptions work, not confirm captured results or obtain approval.","Correct: systematically studying existing documents is research, while interacting with stakeholders in interviews is collaborative elicitation.","The activities are aimed at learning about practice; existence of a policy does not make the elicitation confirmatory."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–64","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q149","domains":[3],"level":3,"tag":"Stakeholder","q":"A detailed process model is needed by analysts, while executives need to decide whether to fund a change. Which communication plan is best?","opts":["Send the model to everyone and let each audience determine what matters","Prepare audience-appropriate formats and detail, keeping the underlying information aligned","Send only the executive summary and ask analysts to infer the process details","Allow each team to edit its own copy so the information matches its needs"],"answer":[1],"why":["A single detailed model may not support the executives' decision efficiently, even if analysts need it.","Correct: tailor the format and level of detail to audience and purpose while preserving consistency of the underlying information.","An executive summary may omit details analysts need to specify or analyze the process.","Independent edits can create conflicting versions and undermine shared understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q150","domains":[3],"level":3,"tag":"Stakeholder","q":"A BA sends a requirements summary to all stakeholder representatives. One representative says a key exception was omitted. What should the BA do?","opts":["Treat the sent summary as final because it was distributed to the agreed audience","Ask the representative to change the requirement directly in the repository","Clarify the intended content, address the omission, and communicate the updated information to relevant stakeholders","Wait for formal approval before discussing the omission"],"answer":[2],"why":["Distribution does not establish that the information is complete or understood.","Uncoordinated direct edits may bypass information management and leave other stakeholders unaware.","Correct: resolve the information gap and communicate the resulting information to the audience that needs it.","Waiting for approval may preserve a known omission and delay shared understanding; clarify it through communication first."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q151","domains":[3],"level":3,"tag":"Stakeholder","q":"A stakeholder asks for a decision rationale that contains sensitive details. The stakeholder needs to understand the decision but is not authorized to see every detail. What is the best communication choice?","opts":["Provide an audience-appropriate explanation that supports understanding while respecting access constraints","Send the full rationale because transparency always overrides access limits","Withhold all explanation because some details are restricted","Ask the stakeholder to request access to the complete file before communicating anything"],"answer":[0],"why":["Correct: communicate information in a format and level of detail suitable for the audience and purpose, while observing relevant constraints.","Transparency does not remove confidentiality or access restrictions.","Withholding everything may prevent the stakeholder from understanding the decision when an appropriate explanation can be shared.","The stakeholder may not need full access to understand the decision; first consider a suitable communication approach."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q152","domains":[3],"level":3,"tag":"Stakeholder","q":"A stakeholder nods during a walkthrough but later applies a model differently from the BA's intent. What is the most useful conclusion?","opts":["The stakeholder's later use is outside the BA's responsibility once the model was sent","The model has been approved and should not be discussed further","The stakeholder intentionally ignored the explanation","Communication did not yet create shared understanding, so clarify the meaning and check interpretation"],"answer":[3],"why":["Communication is intended to support understanding; evidence of misinterpretation merits follow-up.","Approval and understanding are distinct; formal status does not eliminate ambiguity.","The behavior alone does not establish intent; first address the information and interpretation.","Correct: different interpretations show that shared understanding has not been achieved; clarify and confirm how the information is understood."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q153","domains":[3],"level":4,"tag":"Stakeholder","q":"Operations and compliance stakeholders disagree sharply about a proposed exception process. Each group asks the BA to declare which position is correct. What should the BA do first?","opts":["Choose the position with lower implementation cost","Facilitate the groups in clarifying their interests, evidence, and points of agreement before determining what decision is needed","Ask the sponsor to decide without further discussion","Record both positions as agreed alternatives and close the issue"],"answer":[1],"why":["Cost may be relevant later, but selecting on one factor does not manage the collaboration or clarify the disagreement.","Correct: help stakeholders collaborate by surfacing their perspectives and evidence, then identify whether an authorized decision is needed.","A sponsor decision may ultimately be required, but bypassing discussion can lose relevant information and agreement opportunities.","Disagreement is not agreement; recording both as agreed alternatives misrepresents stakeholder status."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q154","domains":[3],"level":4,"tag":"Stakeholder","q":"A key subject matter expert can attend only one of four planned sessions. The sessions cover overlapping topics. How should the BA best maintain collaboration?","opts":["Require the expert to attend all sessions or remove their input from the initiative","Have another stakeholder represent the expert without checking the expert's views","Adapt the collaboration approach to capture the expert's input at a workable time and share relevant outcomes for follow-up","Proceed with all sessions and send the expert the final decisions"],"answer":[2],"why":["This creates an unnecessary all-or-nothing choice and may exclude valuable expertise.","A representative may not know the expert's views; substitution should not be assumed.","Correct: adapt the collaboration approach to the stakeholder's constraints while maintaining opportunities to contribute and review relevant outcomes.","Sharing only final decisions is too late for the expert to influence the analysis or resolve misunderstandings."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q155","domains":[3],"level":4,"tag":"Stakeholder","q":"A stakeholder repeatedly challenges workshop decisions after the meeting, although they had an opportunity to participate. What should the BA do next?","opts":["Clarify the decision and participation process with the stakeholder, explore any unresolved concern, and agree how future input will be handled","Exclude the stakeholder from future collaboration because they missed the opportunity","Reverse the decision automatically to restore the relationship","Ask the project manager to prohibit further comments"],"answer":[0],"why":["Correct: manage collaboration by understanding the concern, clarifying how decisions were reached, and agreeing on constructive future participation.","Exclusion may deepen the conflict and lose relevant input; first understand the concern.","A challenge does not itself show that the decision is wrong; reassess based on evidence and authority.","Prohibiting comments does not address the underlying concern or support effective collaboration."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q156","domains":[3],"level":4,"tag":"Stakeholder","q":"A stakeholder's role changes midway through the initiative, reducing their availability but increasing their decision authority. What should the BA do?","opts":["Keep the original collaboration plan because the initiative has already started","Transfer all engagement to the stakeholder's former colleague","Assume the stakeholder no longer needs information because availability is lower","Reassess engagement needs and adjust the collaboration approach to reflect the changed role, authority, and availability"],"answer":[3],"why":["The stakeholder context changed, so the plan may no longer fit.","A former colleague may not hold the new authority or represent the stakeholder's current responsibilities.","Reduced availability does not eliminate the need for appropriate involvement, especially with changed decision authority.","Correct: revisit stakeholder characteristics and adapt engagement so participation remains appropriate to the changed context."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–78","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q157","domains":[3],"level":5,"tag":"Stakeholder","q":"A requirement has been reviewed by users and a subject matter expert, but the agreed process names a product owner as approver. How should the BA report its status?","opts":["Approved because all reviewers support it","Awaiting approval by the designated product owner","Validated and therefore implicitly approved","Approved unless the product owner objects"],"answer":[1],"why":["Review support does not replace the approval required by the agreed process.","Correct: the requirement remains awaiting approval until the designated authority's approval is obtained.","Validation and approval are distinct; validation does not imply formal approval.","Silence is not approval unless the agreed process explicitly defines such a rule."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q158","domains":[3],"level":5,"tag":"Stakeholder","q":"A designated approver approves a requirement version. A later wording change is made to address a review comment, but no new approval is recorded. What should the BA do?","opts":["Treat the changed wording as approved because the earlier version was approved","Delete the earlier approval record so only the current wording remains","Maintain a clear link between the approved version and the changed version, and determine whether the change requires renewed approval under the agreed process","Ask the implementer to decide whether the wording change is material"],"answer":[2],"why":["Approval of one version does not automatically establish approval of a later revision.","Removing history weakens the decision record and traceability.","Correct: preserve version and approval status and follow the agreed process to determine whether the revised requirement needs approval.","Implementation judgment does not replace the approval process or the designated authority's decision."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q159","domains":[3],"level":5,"tag":"Stakeholder","q":"An approver rejects a requirement but offers a condition under which it could be acceptable. What is the best BA response?","opts":["Record the rejection and condition, communicate the status, and work with relevant stakeholders on whether to revise and resubmit","Change the status to approved with conditions without checking the approval process","Remove the requirement because rejection is final in every case","Ask a different stakeholder to approve the unchanged requirement"],"answer":[0],"why":["Correct: accurately record and communicate the decision, then determine with stakeholders whether a revision and resubmission is appropriate.","Do not invent a conditional approval status unless the agreed process and approver establish it.","The stated condition indicates possible follow-up; do not assume rejection permanently prevents revision.","Seeking another approver for the unchanged item may bypass authority and does not address the stated condition."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q160","domains":[3],"level":5,"tag":"Stakeholder","q":"A business owner approves a requirement, while a security stakeholder objects that a mandatory control is missing. What should the BA do?","opts":["Treat the business owner's approval as sufficient and record the security concern for implementation","Ask the security stakeholder to approve on behalf of the business owner","Mark the requirement approved because one authorized stakeholder agreed","Clarify the applicable approval authority and process, record the unresolved objection, and obtain the required review or decision before treating approval as complete"],"answer":[3],"why":["A mandatory unresolved control may affect the requirement; recording it only for implementation could leave approval incomplete.","The security stakeholder may not have authority to approve for the business owner.","One approval does not necessarily satisfy all required approvals or resolve a material objection.","Correct: establish the required authority and process, keep the objection visible, and do not misstate approval status while required decisions remain unresolved."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–102","multi":false,"sourceSet":"ecba-20-timed-practice-set-18.html"},{"id":"q161","domains":[3],"level":1,"tag":"Stakeholder","q":"After several elicitation sessions, the BA team notices repeated rework caused by unclear session objectives. What is the most useful first step in identifying a performance improvement?","opts":["Replace the elicitation technique across all projects","Ask the sponsor to rate the analysts","Examine the observed performance and its causes against the team's expected performance","Add a mandatory approval checkpoint to each session"],"answer":[2],"why":["A technique change is a possible action, but the cause should be understood first.","Sponsor feedback may help, but one opinion does not establish the performance gap or its cause.","Correct: identify performance gaps and investigate causes before selecting improvement actions.","An approval checkpoint assumes a cause and may add delay without addressing unclear objectives."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–55","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q162","domains":[3],"level":1,"tag":"Stakeholder","q":"A BA lead wants to know whether a new review checklist improved deliverable quality. Which evidence is most useful?","opts":["Compare relevant quality measures before and after using the checklist, accounting for other changes","Ask analysts whether they like the checklist","Count how many times the checklist was opened","Compare the number of deliverables produced, regardless of defects"],"answer":[0],"why":["Correct: comparable measures provide evidence about whether the intended performance outcome changed, while other changes should be considered.","Preference feedback is useful context but does not show whether deliverable quality improved.","Usage indicates adoption, not whether quality improved.","Output volume alone does not measure the targeted quality outcome."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–55","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q163","domains":[3],"level":1,"tag":"Stakeholder","q":"A service owner needs a decision brief; frontline staff need a process explanation. Which communication choice best serves both groups?","opts":["Send the same detailed process model to both groups","Let each group rewrite the requirements to match its terminology","Send only the decision brief and ask staff to request details","Tailor format and detail to each audience while keeping the underlying information consistent"],"answer":[3],"why":["One detailed model may not suit the service owner's decision purpose.","Independent rewrites can introduce inconsistency and change meaning without coordination.","The brief may omit the process detail staff need to understand the change.","Correct: communication should fit the audience and purpose without creating conflicting versions of the information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q164","domains":[3],"level":1,"tag":"Stakeholder","q":"A stakeholder interprets a proposed rule differently from the BA, although the document was distributed as planned. What is the best next step?","opts":["Treat distribution as confirmation that the information was understood","Ask the stakeholder to approve the document again","Change the wording in the repository without further discussion","Clarify the intended meaning and check that the stakeholder's interpretation now aligns"],"answer":[3],"why":["Distribution does not establish shared understanding.","Approval does not by itself resolve what the stakeholder understood.","A silent edit leaves the interpretation gap unresolved and may surprise other readers.","Correct: clarify the information and verify the interpretation to establish shared understanding."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q165","domains":[3],"level":2,"tag":"Stakeholder","q":"A product team has limited capacity. A compliance requirement is mandatory, while two usability requirements compete for the remaining capacity. What is the best prioritization approach?","opts":["Rank all items by expected customer benefit, including the mandatory control","Treat mandatory status as a constraint, then compare the discretionary items using agreed prioritization criteria","Implement the compliance item first and defer all other prioritization until delivery","Ask the loudest stakeholder to rank the usability items"],"answer":[1],"why":["Mandatory status should not be traded away against discretionary benefit; treat it as a constraint.","Correct: preserve mandatory obligations and use agreed criteria to compare feasible discretionary requirements.","The mandatory item may be scheduled first, but the team still needs to prioritize the remaining items.","Influence or volume of advocacy is not a substitute for agreed criteria and evidence."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q166","domains":[3],"level":2,"tag":"Stakeholder","q":"Two requirements have similar business value. One enables several other requirements; the other is independent but requested by an executive. How should the BA support prioritization?","opts":["Place the executive's request first because of the requester's authority","Use delivery cost alone to rank the items","Consider dependency, value, risk, and stakeholder constraints using the agreed criteria","Give them equal priority because their value estimates are similar"],"answer":[2],"why":["Authority may affect decision rights, but does not alone establish priority.","Cost is relevant but cannot capture dependency, value, or risk by itself.","Correct: compare relevant criteria, including dependencies and constraints, rather than relying on one factor.","Similar value estimates do not erase the enabling dependency or other trade-offs."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q167","domains":[3],"level":2,"tag":"Stakeholder","q":"A proposed future state promises faster service, but stakeholders disagree on what “faster” means and how success will be judged. What should the BA do?","opts":["Define measurable outcomes and target conditions with stakeholders before selecting a change strategy","Choose the most ambitious target to create alignment","Use the current average as the future-state target without discussion","Select a solution first and let its performance define the future state"],"answer":[0],"why":["Correct: define the desired outcomes and measurable future-state conditions with stakeholders so options can be assessed against them.","An ambitious target without evidence or agreement may be infeasible and does not define success.","The current state is a baseline, not automatically the desired future state.","The future state guides solution choices; it should not be defined retrospectively by a selected solution."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q168","domains":[3],"level":2,"tag":"Stakeholder","q":"A future-state assessment shows improved customer wait time but increased staff workload and operating cost. What is the best response?","opts":["Keep the future-state definition focused on customer outcomes only","Treat the future state as achieved because one measure improves","Revise the target so no stakeholder group experiences a trade-off","Assess the relevant outcomes and constraints across affected stakeholders before confirming the future state"],"answer":[3],"why":["A one-sided view may conceal material effects on the enterprise and other stakeholders.","One improved measure does not demonstrate that the whole desired outcome is met.","The BA cannot assume every trade-off can be eliminated; make the outcomes and constraints explicit.","Correct: consider multiple outcomes and stakeholder impacts to define a balanced, achievable future state."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q169","domains":[3],"level":3,"tag":"Stakeholder","q":"A new service model requires role changes, data migration, and temporary parallel operations. Which change-strategy choice is most appropriate?","opts":["Select a single release date based on the technology team's estimate","Choose a phased or other transition approach after assessing dependencies, readiness, risks, and stakeholder impacts","Let each department choose its own transition with no shared coordination","Delay strategy decisions until implementation is nearly complete"],"answer":[1],"why":["A date estimate alone does not address dependencies, readiness, or impacts.","Correct: define a change strategy that considers transition states, dependencies, risks, and stakeholder readiness.","Uncoordinated transitions can create incompatible states and unmanaged cross-department dependencies.","Late strategy decisions leave insufficient time to plan the transition and address risk."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–132","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q170","domains":[3],"level":3,"tag":"Stakeholder","q":"Stakeholders agree on the desired future state but disagree about whether to pilot or migrate all users at once. What analysis best informs the change strategy?","opts":["Compare the alternatives against risk, readiness, constraints, and expected outcomes, including transition impacts","Choose a pilot automatically because pilots are always lower risk","Choose full migration because it reaches the future state sooner","Ask the sponsor to select a schedule before analyzing alternatives"],"answer":[0],"why":["Correct: compare viable strategies using relevant risks, readiness, constraints, outcomes, and transition effects.","A pilot can reduce some risks but may create others; it is not universally best.","Faster transition does not necessarily mean lower risk or better overall outcome.","The sponsor may decide, but analysis should make the trade-offs clear first."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–132","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q171","domains":[3],"level":3,"tag":"Stakeholder","q":"A requirement is clear and testable, but stakeholders say it would not solve the underlying business problem. What should the BA conclude?","opts":["It is validated because it is testable","It is verified but not necessarily valid; assess alignment to the need and desired outcome","It is approved because stakeholders reviewed it","It should be rewritten only if implementation is infeasible"],"answer":[1],"why":["Testability supports verification but does not prove the requirement addresses the need.","Correct: verification checks quality and consistency; validation assesses whether requirements support the business need and value.","Review is not the same as approval, and approval does not establish fit to the need.","A requirement can be feasible yet fail to solve the problem; validation is still needed."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q172","domains":[3],"level":3,"tag":"Stakeholder","q":"A set of requirements appears individually reasonable, but the combined solution exceeds the approved budget and misses a required outcome. What should the BA do in validation?","opts":["Validate each requirement separately and leave the combined outcome to delivery","Ask the sponsor to approve the set because each requirement has a stakeholder","Assess the set's alignment with the business need and desired outcomes, and identify gaps or conflicts","Remove the most expensive requirement without checking its value"],"answer":[2],"why":["Individual plausibility does not establish that the set supports the overall need and outcomes.","Stakeholder approval does not substitute for evaluating whether the requirements collectively deliver value within constraints.","Correct: validate the requirements as a set against the business need, desired outcomes, and relevant constraints.","Cost alone does not establish which requirement should be removed; assess contribution and impact."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q173","domains":[3],"level":4,"tag":"Stakeholder","q":"A recommended design has the highest forecast benefit but depends on an untested vendor capability. Another option has lower benefit and proven delivery. What should the BA recommend?","opts":["Recommend the highest-benefit design because forecast value is the primary criterion","Recommend the proven option because untested dependencies must always be rejected","Present the value, assumptions, risks, and evidence for each option, then recommend based on the agreed decision criteria","Defer all recommendation until the vendor capability is proven, regardless of timing"],"answer":[2],"why":["Forecast benefit is important but does not by itself resolve material assumptions and risks.","An untested dependency may be manageable; rejecting it automatically ignores potential value and mitigation.","Correct: compare potential value and risk transparently against the decision criteria, then make a justified recommendation.","Further evidence may help, but a blanket deferral ignores decision timing and possible ways to reduce uncertainty."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–165","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q174","domains":[3],"level":4,"tag":"Stakeholder","q":"A solution option meets the stated requirements but creates a new regulatory exposure for a stakeholder group. What should the BA do before recommending it?","opts":["Analyze the exposure's effect on potential value, feasibility, and stakeholder outcomes, and compare alternatives","Treat the exposure as outside scope because the requirements are met","Recommend the option and leave the exposure for the compliance team to discover","Reject the option without assessing whether the exposure can be mitigated"],"answer":[0],"why":["Correct: compare options using value and relevant risks, constraints, and stakeholder impacts before recommending a solution.","Meeting requirements does not make a material regulatory impact irrelevant to solution value or feasibility.","Deferring a known exposure hides information needed for an informed recommendation.","The exposure may be mitigable; assess its impact and alternatives rather than rejecting automatically."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–165","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q175","domains":[3],"level":4,"tag":"Stakeholder","q":"A new self-service solution reduces call volume, but accessibility complaints rise. Which measure set best evaluates solution performance?","opts":["Call volume alone, because it was the primary business case measure","Accessibility complaints alone, because they indicate stakeholder harm","Total transaction count and system uptime only","A balanced set of measures tied to desired outcomes, including service efficiency and accessibility"],"answer":[3],"why":["Call volume alone can hide a deterioration in accessibility or other outcomes.","Complaints matter but alone do not show whether other desired outcomes are met.","Volume and uptime measure activity and technical availability, not the full business and stakeholder outcomes.","Correct: measure performance against the desired outcomes, including both efficiency and accessibility."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–169","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q176","domains":[3],"level":4,"tag":"Stakeholder","q":"A dashboard shows a target was met for one month after launch. What is the strongest basis for concluding the solution is performing as intended?","opts":["The target was met once, so continued monitoring is unnecessary","Compare suitable performance measures with baselines and targets over an appropriate period, considering context and data quality","Ask the solution owner whether performance feels stable","Use the number of active users as a substitute for all outcome measures"],"answer":[1],"why":["A single period may be atypical and does not establish sustained performance.","Correct: measure solution performance against appropriate baselines and targets over time, with attention to context and reliable data.","Owner judgment may inform interpretation but cannot replace performance evidence.","Usage is an adoption indicator, not a proxy for every outcome or performance measure."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–169","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q177","domains":[3],"level":5,"tag":"Stakeholder","q":"Across three initiatives, review cycles are consistently delayed. One team attributes this to stakeholder availability; another suspects unclear review criteria. What should the BA practice lead do?","opts":["Mandate one review tool across all initiatives before comparing causes","Use the earliest team estimate as the benchmark and require other teams to match it","Compare evidence and context across initiatives, determine contributing causes, and select improvement actions with measures to evaluate their effect","Ask sponsors to rank teams by speed and reward the fastest"],"answer":[2],"why":["A shared tool may help later, but it assumes the cause and could fail to address it.","One team's timing may reflect different scope or context; it is not a sufficient benchmark by itself.","Correct: identify patterns and causes across contexts, then choose and evaluate targeted performance improvements.","Speed alone can reward rushed reviews and does not establish quality or root causes."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–55","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q178","domains":[3],"level":5,"tag":"Stakeholder","q":"A solution meets its adoption target, but users still rely on manual workarounds and the expected benefit is not realized. What should the BA recommend first?","opts":["Increase adoption targets to encourage more use","Investigate performance evidence and causes of the gap, then compare feasible actions with stakeholders","Replace the solution immediately because the expected benefit was missed","Report the adoption target as success and close evaluation"],"answer":[1],"why":["Raising the target does not explain why benefits are missing or address workarounds.","Correct: identify the value gap and its causes, then assess appropriate actions with stakeholders.","Replacement may be an option, but immediate selection without cause analysis risks repeating the problem.","Adoption is only one measure; closing evaluation ignores the unmet benefit and workaround evidence."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q179","domains":[3],"level":5,"tag":"Stakeholder","q":"A benefit gap may be caused by incomplete training, a policy bottleneck, or a solution limitation. Which recommendation process is strongest?","opts":["Compare targeted actions for each evidenced cause, including value, cost, risk, and stakeholder impact","Select training because it is typically the least expensive action","Ask the solution vendor to choose the action because it knows the product","Recommend all actions at once so no cause is missed"],"answer":[0],"why":["Correct: connect actions to evidenced causes and compare expected value and impacts before recommending.","Lower cost does not establish that training addresses the policy bottleneck or solution limitation.","Vendor product knowledge is useful, but the recommendation must consider enterprise outcomes and stakeholder impacts.","Doing everything may be infeasible and does not compare the value or risks of alternatives."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q180","domains":[3],"level":5,"tag":"Stakeholder","q":"A proposed improvement could raise throughput but shift work and cost to a partner organization. What should the BA include in the recommendation?","opts":["Throughput improvement only, because partner operations are outside the solution boundary","A recommendation to reject the change without quantifying the transfer","The partner's cost estimate only, because it captures the principal stakeholder concern","Expected value and impacts across affected parties, including transferred costs, risks, and feasible mitigations"],"answer":[3],"why":["A boundary does not make a material dependency or impact irrelevant to value assessment.","Rejecting without comparison or evidence may overlook mitigations or net value.","Cost is important but does not capture throughput benefits, risks, or possible mitigations.","Correct: assess value and impacts across stakeholders and compare feasible actions, including how costs and risks shift."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":false,"sourceSet":"ecba-20-timed-practice-set-19.html"},{"id":"q181","domains":[3],"level":1,"tag":"Value","q":"A BA team introduces a new review checklist, but review delays remain unchanged. Which next step best supports an evidence-based improvement to business analysis performance?","opts":["Compare performance with the intended outcome and investigate why the checklist did not reduce delays","Require every analyst to use the checklist more often","Replace the checklist with a new template before reviewing results","Measure how many checklist fields analysts complete"],"answer":[0],"why":["Correct: compare actual performance with the expected result and investigate contributing causes before choosing another action.","Greater use may not help if the checklist does not address the cause of delays.","Changing the template without analyzing the result risks repeating the same problem.","Completion counts show use, not whether review performance improved."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–55","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q182","domains":[3],"level":1,"tag":"Value","q":"A practice lead wants to show whether a new elicitation approach creates value for the organization. Which measure is most informative?","opts":["The number of sessions held using the approach","Analyst satisfaction with the approach alone","Change in relevant outcomes such as rework or decision time, compared with a suitable baseline","The percentage of analysts trained, without outcome data"],"answer":[2],"why":["Session volume measures activity, not its effect on business analysis performance.","Satisfaction provides useful feedback but does not demonstrate organizational value by itself.","Correct: evaluate the outcome the improvement was intended to affect against relevant baseline information.","Training completion shows readiness or adoption, not whether value was realized."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–55","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q183","domains":[3],"level":1,"tag":"Value","q":"Finance executives need to decide whether to fund a change, while operational stakeholders need to understand how it affects their work. Which communication approach best supports value decisions?","opts":["Send both groups the detailed requirements and let them identify the relevant value","Allow each group to alter the value statements to fit its priorities","Send only the business case because it contains the value estimate","Tailor information and detail to each audience's decision or work needs while keeping the underlying facts consistent"],"answer":[3],"why":["The same detailed package may not support each audience's purpose efficiently or clearly.","Uncoordinated changes to value statements can create inconsistent claims and expectations.","A business case alone may omit operational impacts stakeholders need to understand.","Correct: communicate value in a form suited to each audience while preserving a consistent information base."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q184","domains":[3],"level":1,"tag":"Value","q":"A benefit estimate is shared with stakeholders, but some assume it is guaranteed while others understand it as conditional on adoption. What should the BA do?","opts":["Treat the estimate as understood because it was included in the presentation","Remove the estimate to avoid disagreement","Ask the sponsor to confirm the benefit after implementation","Clarify the assumptions and conditions behind the estimate, then confirm stakeholders understand them"],"answer":[3],"why":["Distribution does not show that stakeholders share the same interpretation.","Removing useful value information avoids rather than resolves the misunderstanding.","The sponsor's later confirmation does not correct current uncertainty about assumptions.","Correct: clarify what the estimate depends on and check that the audience understands its meaning and limits."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–70","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q185","domains":[3],"level":2,"tag":"Value","q":"A high-value customer feature competes with a lower-value control required by regulation. How should the BA support prioritization?","opts":["Rank both by estimated value and deliver whichever scores higher","Treat the regulatory control as a constraint, then compare feasible discretionary work using agreed value criteria","Prioritize the control only if its direct financial value exceeds the feature","Let the customer-facing stakeholder decide because customer value is the goal"],"answer":[1],"why":["A mandatory obligation should not be traded away solely because another item scores higher on discretionary value.","Correct: account for mandatory constraints first, then prioritize feasible work using agreed criteria.","Regulatory obligations do not depend on a higher direct financial return.","Customer value matters, but it does not override mandatory requirements or agreed decision authority."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q186","domains":[3],"level":2,"tag":"Value","q":"Two requirements promise similar benefits. One enables a later capability with substantial value; the other can be delivered independently this quarter. What is the best prioritization response?","opts":["Prioritize the independent item because it produces earlier visible value","Assign equal priority because the estimated benefits are similar","Consider dependency, timing, risk, and value contribution using the agreed criteria","Prioritize the enabling item automatically because dependencies always take precedence"],"answer":[2],"why":["Earlier value is relevant but does not by itself account for the enabling item's downstream contribution.","Similar benefit estimates do not make their timing, risk, or dependencies equivalent.","Correct: consider the items' value and dependencies in context against the agreed prioritization criteria.","Dependencies matter, but they do not automatically outweigh all other value and risk considerations."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q187","domains":[3],"level":2,"tag":"Value","q":"Stakeholders define success as faster service, fewer errors, and lower operating cost. These targets conflict under the current budget. What should the BA do when defining the future state?","opts":["Work with stakeholders to define measurable outcomes, priorities, and acceptable trade-offs within constraints","Select the outcome with the largest estimated financial return","Keep all three targets unchanged and let solution design resolve the conflict","Set targets equal to current performance until funding is approved"],"answer":[0],"why":["Correct: define a measurable future state with stakeholders, making priorities and constraints explicit so value can be assessed.","Financial return is relevant but does not alone resolve stakeholder trade-offs or nonfinancial outcomes.","Leaving the conflict unresolved makes it difficult to evaluate options against a coherent future state.","Current performance is a baseline, not automatically the desired future state; funding status does not define value targets."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"},{"id":"q188","domains":[3],"level":2,"tag":"Value","q":"A proposed future state improves average processing time but worsens service for customers who need accessibility support. Which response best defines value?","opts":["Use the average improvement as the future-state measure because it represents most customers","Define outcomes and measures that reflect affected stakeholder groups and relevant constraints, not only the average","Drop the accessibility outcome because it is difficult to quantify","Set the future state to avoid every possible negative impact, regardless of feasibility"],"answer":[1],"why":["An average can conceal significant negative effects on a stakeholder group.","Correct: define future-state outcomes and measures that account for affected stakeholders and constraints.","Difficulty of measurement does not make a material outcome irrelevant; identify a suitable measure or evidence.","A future state should be achievable and informed by trade-offs, not an unexamined promise to eliminate every impact."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-20-timed-practice-set-20.html"}]);